package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct {
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64            // PIC 9(1) @15 len=1
}

var WsEofFlag string = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0)
var WsYear int64 = 0
var WsCount int64 = 0
var WsBalEd string = ""

var SchedRecVar SchedRec
var schedFile *os.File
var schedReader *bufio.Reader
var inputDone bool

func formatPIC9(n int64, digits int) string {
	s := fmt.Sprintf("%d", n)
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func formatZZZZZZZZ9_99(v decimal.Decimal) string {
	// PIC ZZ,ZZZ,ZZ9.99 width 13
	// v has scale 2, non-negative
	// Handle overflow: keep low-order 8 integer digits
	rounded := v.Round(2)
	// Ensure not negative zero
	if rounded.IsNegative() {
		rounded = rounded.Neg()
	}
	// Get integer and fractional parts
	// Use Truncate to get integer part
	intPart := rounded.Truncate(0)
	fracPart := rounded.Sub(intPart).Abs()
	// frac is 0..99
	// To avoid decimal issues, get via string or via Mul
	// Use intPart and frac calculation via decimal
	fracInt := fracPart.Mul(decimal.NewFromInt(100)).Round(0).IntPart()
	// intPart may be large; keep low 8 digits
	intVal := intPart.IntPart()
	// If overflow negative? not needed
	// Extract 8 digits low order
	intDigits := 8
	// Build int string 8 chars zero padded with overflow truncation
	intStrFull := fmt.Sprintf("%d", intVal)
	// Handle overflow truncation of high-order digits
	if len(intStrFull) > intDigits {
		intStrFull = intStrFull[len(intStrFull)-intDigits:]
	} else if len(intStrFull) < intDigits {
		intStrFull = strings.Repeat("0", intDigits-len(intStrFull)) + intStrFull
	}
	// Now apply ZZ,ZZZ,ZZ9 pattern
	// Positions: 0:Z,1:Z,2:',',3:Z,4:Z,5:Z,6:',',7:Z,8:Z,9:9,10:'.',11:9,12:9
	// But for formatting, '.' at 10
	// Build integer formatted part (first 10 chars including commas)
	// mapping digit index to picture char
	picInt := []byte("ZZ,ZZZ,ZZ9") // len 9? wait count: Z Z , Z Z Z , Z Z 9 = 9? Actually "ZZ,ZZZ,ZZ9" = 2+1+3+1+2+1 =10
	// Let's define correctly: "ZZ,ZZZ,ZZ9.99" -> integer pic = "ZZ,ZZZ,ZZ9" (10 chars)
	picInteger := "ZZ,ZZZ,ZZ9"
	// intStrFull is 8 digits aligned to pic placeholders that are Z or 9
	// Need to map digits to placeholder positions
	// Collect placeholder indices
	type ph struct{ pos int; isNine bool }
	var placeholders []ph
	for i, c := range picInteger {
		if c == 'Z' || c == '9' {
			placeholders = append(placeholders, ph{i, c == '9'})
		}
	}
	// placeholders should be 8
	formattedInt := make([]byte, len(picInteger))
	for i, c := range picInteger {
		formattedInt[i] = byte(c)
	}
	for i, p := range placeholders {
		d := intStrFull[i] // i corresponds digit index 0..7
		formattedInt[p.pos] = d
	}
	// Now suppress leading zeros: for each placeholder left to right, if digit is '0' and it's Z, replace with space, continue; if non-zero, break. But commas inside suppressed zone become spaces.
	// The last placeholder is '9' never suppressed.
	suppressing := true
	for idx, p := range placeholders {
		if !suppressing {
			break
		}
		if p.isNine {
			// This is the last '9', never suppressed even if zero, but suppression stops before it if we reached it with all zeros
			// If all previous were zeros, this zero should remain '0'
			break
		}
		digitChar := formattedInt[p.pos]
		if digitChar == '0' {
			formattedInt[p.pos] = ' '
			_ = idx
		} else {
			suppressing = false
		}
	}
	// Replace commas that are in suppressed zone with spaces
	// A comma is in suppressed zone if all placeholders to its left are suppressed (i.e., are spaces) and all placeholders to its right that are before next non-suppressed? Simpler: comma becomes space if every digit placeholder to its left is space (i.e., suppressed zeros) -> no significant digit to left.
	// Actually COBOL: commas inside suppressed zone become spaces.
	for i, c := range formattedInt {
		if c == ',' {
			// check if any non-space digit to left
			hasLeft := false
			for j := 0; j < i; j++ {
				if formattedInt[j] != ' ' && formattedInt[j] != ',' {
					// digit present
					hasLeft = true
					break
				}
			}
			if !hasLeft {
				formattedInt[i] = ' '
			}
		}
	}
	fracStr := fmt.Sprintf("%02d", fracInt)
	result := string(formattedInt) + "." + fracStr
	return result
}

func parseDecimalFromDigits(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.NewFromInt(0)
	}
	// digits only, may contain spaces? treat spaces as 0? but assume digits
	// Remove non-digit
	clean := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			clean += string(ch)
		}
	}
	if clean == "" {
		return decimal.NewFromInt(0)
	}
	d := decimal.RequireFromString(clean)
	if scale != 0 {
		d = d.Shift(-scale)
	}
	return d
}

func parseSchedRec(line string) SchedRec {
	// pad to 16
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	}
	if len(line) > 16 {
		line = line[:16]
	}
	acct := line[0:4]
	prinStr := line[4:11]
	rateStr := line[11:15]
	yearsStr := line[15:16]
	pr := parseDecimalFromDigits(prinStr, 2)
	ra := parseDecimalFromDigits(rateStr, 2)
	var y int64 = 0
	yearsStr = strings.TrimSpace(yearsStr)
	if yearsStr != "" {
		// digits
		val := 0
		for _, c := range yearsStr {
			if c >= '0' && c <= '9' {
				val = val*10 + int(c-'0')
			}
		}
		y = int64(val)
	}
	return SchedRec{ScAcct: acct, ScPrin: pr, ScRate: ra, ScYears: y}
}

func main() {
	var err error
	schedFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer schedFile.Close()
	schedReader = bufio.NewReader(schedFile)

	MAINPARA()
}

func MAINPARA() {
	// OPEN INPUT SCHED-FILE
	READPARA()
	for !inputDone {
		PROCESSPARA()
	}
	// CLOSE
	schedFile.Close()
	// DISPLAY "SCHEDULES: " WS-COUNT
	// WsCount is PIC 99 zero-padded 2
	fmt.Printf("SCHEDULES: %s\n", formatPIC9(WsCount, 2))
}

func READPARA() {
	line, err := schedReader.ReadString('\n')
	if err != nil {
		// EOF
		// check if line still has content without newline
		if len(line) > 0 {
			// trim trailing \r\n
			line = strings.TrimRight(line, "\r\n")
			SchedRecVar = parseSchedRec(line)
			// This record is valid, next read will be EOF
			// But we need to handle AT END only when no record
			// We have consumed one record, so not done yet
			// Need to stash? Simpler: we got data, return and next call will hit EOF
			// However we have already read it; we set not done
			// Need to ensure next call detects EOF. We can push back by using a flag
			// Instead handle: if err == io.EOF and line != "" we have a record
			// So we should not set done, but remember that next read is EOF
			// Use a buffered reader: we already consumed, so next read will be EOF
			inputDone = false
			WsEofFlag = "N"
			return
		}
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	line = strings.TrimRight(line, "\r\n")
	SchedRecVar = parseSchedRec(line)
	inputDone = false
	WsEofFlag = "N"
}

func PROCESSPARA() {
	WsBal = SchedRecVar.ScPrin
	// Need to truncate to PIC 9(8)V99 scale 2 (just in case)
	WsBal = WsBal.Truncate(2)
	WsYear = 1
	for WsYear <= SchedRecVar.ScYears {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		rateDiv := SchedRecVar.ScRate.Shift(-2)
		factor := decimal.NewFromInt(1).Add(rateDiv)
		computed := WsBal.Mul(factor)
		// ROUNDED to scale 2
		computed = computed.Round(2)
		// store truncation to target scale (already 2) and low-order truncation
		WsBal = computed.Truncate(2)
		WsBalEd = formatZZZZZZZZ9_99(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		yearStr := formatPIC9(WsYear, 2)
		fmt.Printf("%s Y%s %s\n", SchedRecVar.ScAcct, yearStr, WsBalEd)
		WsYear++
	}
	WsBalEd = formatZZZZZZZZ9_99(WsBal)
	fmt.Printf("%s FINAL %s\n", SchedRecVar.ScAcct, WsBalEd)
	WsCount++
	READPARA()
}

